package com.hbm.machine.oilextraction;
import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class OilExtractionContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> BES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final Map<OilDrillKind,DeferredBlock<OilDrillBlock>> BLOCK=new EnumMap<>(OilDrillKind.class);public static final Map<OilDrillKind,DeferredItem<OilDrillItem>> ITEM=new EnumMap<>(OilDrillKind.class);public static final Map<OilDrillKind,DeferredHolder<BlockEntityType<?>,BlockEntityType<OilDrillEntity>>> ENTITY=new EnumMap<>(OilDrillKind.class);
 static{for(var kind:OilDrillKind.values()){var block=BLOCKS.register(kind.id,()->new OilDrillBlock(kind));BLOCK.put(kind,block);ITEM.put(kind,ITEMS.register(kind.id,()->new OilDrillItem(block.get())));ENTITY.put(kind,BES.register(kind.id,()->BlockEntityType.Builder.of(OilDrillEntity::new,block.get()).build(null)));}}
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<OilDrillPort>> PORT=BES.register("oil_drill_port",()->BlockEntityType.Builder.of(OilDrillPort::new,BLOCK.get(OilDrillKind.PUMPJACK).get()).build(null));
 public static final DeferredBlock<OilPipeBlock> PIPE=BLOCKS.register("oil_pipe",OilPipeBlock::new);public static final DeferredItem<BlockItem> PIPE_ITEM=ITEMS.registerSimpleBlockItem(PIPE);
 public static final DeferredItem<OilDetectorItem> DETECTOR=ITEMS.register("oil_detector",OilDetectorItem::new);public static final List<DeferredItem<AfterburnUpgradeItem>> AFTERBURN=new ArrayList<>();static{for(int i=1;i<=3;i++){int tier=i;AFTERBURN.add(ITEMS.register("upgrade_afterburn_"+i,()->new AfterburnUpgradeItem(tier)));}}
 public static final DeferredHolder<MenuType<?>,MenuType<OilDrillMenu>> MENU=MENUS.register("oil_drill",()->new MenuType<>((IContainerFactory<OilDrillMenu>)OilDrillMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);BES.register(bus);MENUS.register(bus);OilDetectorNotice.register(bus);}
 public static List<ItemStack> creativeStacks(String tab){if(tab.equals("machine"))return ITEM.values().stream().map(item->new ItemStack(item.get())).toList();if(tab.equals("consumable"))return List.of(new ItemStack(DETECTOR.get()));if(tab.equals("control"))return AFTERBURN.stream().map(item->new ItemStack(item.get())).toList();return List.of();}
}
